import {financialMetrics} from '/components/views.js';
import {installBoardDrag,targetsFor} from '/components/board.js';
import {esc,number,money,icon,badge,grade,shell,heading,dashboard,properties,assessments,certificates,initiatives,compliance,reports,propertyTable,pagination} from '/components/views.js';

import {responsiveNavigation,syncNavigationState} from './responsive.js';

import {readPreferences,applyTheme,syncWorkspaceControls} from './preferences.js';

import {openImport} from './imports.js';

const showcaseApi=document.querySelector('meta[name=epc-showcase]')?.content==='sample-only'?(await import('./showcase-api.js')).showcaseApi:null;

const $=s=>document.querySelector(s),s={page:'dashboard',data:{assessments:[],certificates:[],initiatives:[],documents:[],compliance:[]},user:null,csrf:null,config:{},search:'',filter:'',province:'',draft:null,step:0,saving:false,tablePage:1,pageSize:25,compactNav:false};

const app=$('#app'),modal=$('#modal');let saveTimer,previousFocus;

responsiveNavigation();

Object.assign(s,readPreferences());applyTheme(s.theme,false);

try{s.financialAssumptions=JSON.parse(localStorage.getItem('bolide-epc:financial-scenario')||'{}');financialMetrics({kwh:0,tariff:0,cost:0,emission:0},s.financialAssumptions);}catch{s.financialAssumptions={};}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=error?'show error':'show';clearTimeout(t.timer);t.timer=setTimeout(()=>t.className='',6000);}

async function api(path,options={}){

  if(showcaseApi)return showcaseApi(path,options);

  const headers={};if(options.body && !(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}if(s.csrf)headers['X-CSRF-Token']=s.csrf;

  const r=await fetch('/api'+path,{...options,headers:{...headers,...options.headers}});const type=r.headers.get('content-type');const data=type?.includes('json')?await r.json():null;

  if(!r.ok){const e=new Error(data?.error||'Request could not be completed');e.errors=data?.errors;e.status=r.status;throw e;}return data;

}

async function refresh(){s.data=await api('/portfolio');}

function openModal(html){previousFocus=document.activeElement;modal.classList.remove('wide-dialog');modal.innerHTML=`<button class="modal-close icon-button" data-action="close" aria-label="Close dialog">×</button>${html}`;modal.showModal();modal.querySelector('input,select,button')?.focus();}

installBoardDrag({find:id=>s.data.assessments.find(a=>a.id===id),targets:a=>targetsFor(a,s.user,s.config.staticDemo),onMove:moveAssessment,onError:message=>toast(message,true)});
async function moveAssessment(id,status){
 const a=s.data.assessments.find(a=>a.id===id);if(!a||!targetsFor(a,s.user,s.config.staticDemo).includes(status))throw new Error('This stage change is not available for your role.');
 if(status==='Submitted'){
  const result=await api(`/assessments/${id}/validation`);
  if(result.errors.length){openModal(`<h2>Complete the assessment before submission</h2><ul>${result.errors.map(e=>`<li><b>${esc(e.field)}</b> — ${esc(e.message)}</li>`).join('')}</ul><button class="primary" data-action="edit" data-id="${id}">Open assessment</button>`);return;}
 }
 if(['Approved','Revision Required'].includes(status)){
  openModal(`<h2>${status==='Approved'?'Approve assessment':'Request revision'}</h2><p>${esc(a.name)}</p><form id="board-transition-form" data-id="${id}" data-status="${status}">${status==='Approved'?'<label class="check"><input type="checkbox" name="confirmBenchmark" required> I independently verified the benchmark, factors and methodology.</label><label class="check"><input type="checkbox" name="confirmProfessional" required> I independently verified the professional’s registration / authorisation.</label>':'<label class="field">Field requiring revision<input name="field" required maxlength="80"></label><label class="field">Review comment<textarea name="comment" required maxlength="2000"></textarea></label>'}<button class="primary" type="submit">${status==='Approved'?'Approve assessment':'Request revision'}</button></form>`);return;
 }
 await api(`/assessments/${id}/transition`,{method:'POST',body:{status,version:a.version}});await refresh();render();toast(`Assessment moved to ${status}`);
}
function closeModal(){modal.close();previousFocus?.focus();}

function legal(type){if(s.config.staticDemo&&type!=='cookies')return openModal(`<h2>${type==='terms'?'Workspace terms':'Privacy and data handling'}</h2><p>Bolide Energy Pro supports building performance assessment and certificate record management. Authorised professionals remain responsible for verified data and official certification.</p><p>Records and attachments in this workspace are stored on this browser and device. Download a backup to keep a separate copy. This workspace does not synchronise with the company database.</p>`);const texts={privacy:`<h2>Privacy and data handling</h2><p>This workspace stores building information, energy ledgers, professional details and uploaded evidence for EPC assessment and review. Access is scoped to the signed-in organisation.</p><p>Assessment records and evidence are encrypted at rest using the configured server key. Account email addresses, role records and activity metadata are stored in the private database. Session cookies expire after eight hours.</p><p>The public verification page exposes only property ID, certificate numbers, status and validity dates. Building addresses and evidence are not published.</p><p>Hosting location, processors, retention periods, backups, rights requests and the final responsible-party notice must be confirmed by the operator before live use.</p><p>Privacy contact: ${esc(s.config.privacyContact||'Not configured — this installation is not ready for public registration.')}</p>`,terms:`<h2>Workspace terms</h2><p>Bolide Energy Pro supports building assessments, internal review, energy analysis and certificate record management. Authorised professionals remain responsible for verified data, applicable standards and official certification.</p><p>Calculated results rely on recorded inputs and assumptions. Review packs are not official EPCs. SANEDI submission occurs externally. Do not upload evidence without authority to process it.</p><p>Organisation-specific service terms must be approved by the operator before public launch.</p>`,cookies:`<h2>Cookie preferences</h2><p>Only the essential sign-in cookie is used. It is HttpOnly and SameSite Strict, with Secure enabled in production. There are no analytics, advertising cookies or third-party embeds.</p><p>Appearance preferences are optional. Portfolio records and attachments are saved separately in browser storage.</p><label class="check"><input id="theme-pref" type="checkbox" checked> Remember appearance on this browser</label><button class="primary" data-action="cookie-save">Save preferences</button>`};openModal(texts[type]);}

function login(){const invite=new URLSearchParams(location.search).get('invite');app.innerHTML=`<div class="auth-layout"><section class="auth-story"><img src="/assets/bolide-logo.png" alt="Bolide" class="auth-logo"><span class="eyebrow">BOLIDE ENERGY PRO</span><h1>Better buildings.<br>Measured.</h1><p>A connected workspace for energy performance, evidence and confident decisions.</p><div class="auth-bands">${['A','B','C','D','E','F','G'].map(g=>grade(g)).join('')}</div><small>BUILT FOR SOUTH AFRICAN PROPERTY PORTFOLIOS</small></section><section class="auth-form"><div class="eyebrow">YOUR ENERGY WORKSPACE</div><h2>${invite?'Join your organisation':'Welcome to Energy Pro'}</h2><p class="muted">${invite?'Complete your invitation to begin.':'Sign in to your organisation’s private portfolio.'}</p><form id="login-form">${invite?'<label class="field">Full name<input name="name" required maxlength="100" autocomplete="name"></label>':'<label class="field">Email address<input name="email" type="email" required autocomplete="username"></label>'}<label class="field">Password<input name="password" type="password" required ${invite?'minlength="12"':''} maxlength="200" autocomplete="${invite?'new-password':'current-password'}"></label><button class="primary full" type="submit">${invite?'Accept invitation':'Sign in'} ${icon('arrow')}</button><p id="login-error" class="form-error" role="alert"></p></form>${s.config.demo?`<div class="demo-login"><span class="divider-label">EXPLORE THE SYNTHETIC DEMO</span><div class="button-row">${['Admin','Assessor','Reviewer'].map(role=>`<button class="secondary" data-action="demo" data-id="${role}">${role}</button>`).join('')}</div><small>Local demo only. No real credentials or client records.</small></div>`:!s.config.initialized?'<div class="callout">Provision the first administrator using <code>node --env-file=.env scripts/create-admin.js</code> on the server.</div>':''}<div class="auth-links"><button data-action="legal" data-id="privacy">Privacy</button><button data-action="legal" data-id="terms">Terms</button><button data-action="legal" data-id="cookies">Cookie preferences</button></div></section></div>`;}

function render(){

  document.body.classList.toggle('workspace-active',Boolean(s.user));

  document.body.classList.toggle('nav-compact',s.compactNav);

  if(!s.user)return login();

  const views={dashboard,properties,assessments,certificates,savings:initiatives,compliance,reports,team:teamView,wizard:wizard};

  app.innerHTML=shell(s,(views[s.page]||dashboard)(s));

  const main=$('#main'),title=main.querySelector('.page-heading');

  if(title){const body=document.createElement('div');body.className='page-body';while(title.nextSibling)body.append(title.nextSibling);main.append(body);}

  updateConnection();

  syncWorkspaceControls(s);syncNavigationState();

  if(s.config.staticDemo)document.querySelectorAll('[data-action=logout],.account-menu').forEach(el=>el.hidden=true);

}

function updateConnection(){const banner=$('#offline-banner'),label=$('#connection-status');if(banner)banner.hidden=navigator.onLine;if(label){label.classList.toggle('disconnected',!navigator.onLine);label.innerHTML='<span class="dot"></span>'+(s.config.staticDemo?'Saved on this browser':navigator.onLine?'Connected':'Offline');}}

window.addEventListener('online',()=>{updateConnection();toast('Connection restored. You can save or refresh your workspace.');});

window.addEventListener('offline',updateConnection);

function renderPropertyResults(){const table=$('#property-table'),pager=$('#pagination');if(table)table.innerHTML=propertyTable({...s,paginate:true});if(pager)pager.innerHTML=pagination(s);}

function searchWorkspace(){openModal('<h2>Search your workspace</h2><label class="field">Find a property or section<input id="workspace-query" type="search" placeholder="Property, ID, province or section…" autocomplete="off"></label><div id="workspace-results" class="workspace-results"></div>');$('#workspace-query').focus();updateWorkspaceSearch('');}

function updateWorkspaceSearch(query){const q=query.trim().toLowerCase(),result=$('#workspace-results');if(!result)return;const sections=[['dashboard','Overview'],['properties','Properties'],['assessments','Assessments'],['certificates','Certificates'],['savings','Savings initiatives'],['compliance','Compliance centre'],['reports','Reports & audit']].filter(([,title])=>title.toLowerCase().includes(q));const matches=s.data.assessments.filter(a=>`${a.name} ${a.propertyId} ${a.province}`.toLowerCase().includes(q)).slice(0,12);result.innerHTML=sections.map(([id,title])=>`<a href="#${id}" data-action="search-section">${icon('grid')}<span>${esc(title)}</span>${icon('arrow')}</a>`).join('')+matches.map(a=>`<button data-action="search-property" data-id="${a.id}">${icon('building')}<span><b>${esc(a.name)}</b><small>${esc(a.propertyId)} · ${esc(a.province)}</small></span>${grade(a.result?.grade)}</button>`).join('')||'<p class="muted">No matching results.</p>';}

function teamView(){return heading('PEOPLE & PERMISSIONS','Team & access','Invite colleagues with a specific role. Each account belongs to a single organisation.',`<button class="primary" data-action="invite">${icon('plus')} Invite colleague</button>`)+`<section class="panel"><div class="panel-heading"><h2>Organisation members</h2></div><div class="table-wrap"><table><thead><tr><th>NAME</th><th>EMAIL</th><th>ROLE</th></tr></thead><tbody>${(s.team||[]).map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${badge(u.role)}</td></tr>`).join('')}</tbody></table></div></section><div class="callout">${icon('shield')}<span>Assessors prepare submissions. A different authorised reviewer approves them. Administrators manage invitations. Property owners can view organisation records. Super Admin remains scoped to its own organisation.</span></div>`;}

const titles=['Property details','Building systems','Energy ledger','Evidence & audit','Review & submit'];

const systemNames=['Building orientation','Building fabric','Fenestration and shading','Lighting','Hot water','HVAC and ventilation','Renewable energy','Controls and metering','Energy monitoring'];

const provinces=['Eastern Cape','Free State','Gauteng','KwaZulu-Natal','Limpopo','Mpumalanga','North West','Northern Cape','Western Cape'];

const options=(list,value)=>list.map(item=>`<option value="${esc(Array.isArray(item)?item[0]:item)}" ${(Array.isArray(item)?item[0]:item)==value?'selected':''}>${esc(Array.isArray(item)?item[1]:item)}</option>`).join('');

function field(key,label,type='text',extra=''){const value=s.draft?.[key]??'';return `<label class="field">${label}<input name="${key}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="any"':''} ${extra}></label>`;}

function select(key,label,items){return `<label class="field">${label}<select name="${key}">${options(items,s.draft?.[key])}</select></label>`;}

function wizard(){const a=s.draft;if(!a)return '';const locked=!['Draft','Revision Required'].includes(a.status)||!['Admin','Super Admin','Energy Manager','Assessor'].includes(s.user.role);let body='';

  if(s.step===0)body=`<h2>Know the building</h2><p class="section-intro">Capture the building’s identity, occupancy and measured areas.</p><div class="form-grid">${field('name','Property name','text','required maxlength="160"')}${select('ownership','Ownership / occupation',['Private','State'])}${field('address','Physical address','text','required')}${select('province','Province',provinces)}${field('municipality','Municipality')}${field('erf','Erf number')}${field('eskomAccount','Electricity account reference (optional)')}${select('occupancy','Dominant occupancy',[['G1','G1 · Offices'],['A1','A1 · Entertainment and public assembly'],['A2','A2 · Theatrical and indoor sport'],['A3','A3 · Places of instruction']])}${select('zone','Energy zone',['1','2','3','4','5','5H','6','7'])}${field('operationalYears','Years of qualifying operation','number')}${field('gfa','Gross floor area · m²','number')}${field('nfa','Net floor area · m²','number')}${field('vacancyAreaMonths','Vacant area × months · m²-months (total)','number')}</div><label class="check"><input type="checkbox" name="majorRenovation" ${a.majorRenovation?'checked':''}> Major renovation within the past two years</label><div class="callout">${icon('building')}<span>Mandatory screening uses net floor area strictly over 1,000 m² (state) or 2,000 m² (private), qualifying occupancy and operating history. GFA is recorded separately.</span></div>`;

  if(s.step===1)body=`<h2>Technical systems review</h2><p class="section-intro">Nine project checklist sections. These support evidence review and do not replace the licensed SANS clauses or determine the A–G rating.</p>${a.systems.map((sys,i)=>`<section class="system-row"><div><span class="eyebrow">${sys.code}</span><h3>${esc(sys.title)}</h3></div><label class="field">Finding<select data-system="${i}" data-key="status">${options(['Not assessed','Verified','Action needed','Not applicable'],sys.status)}</select></label><label class="field system-note">Evidence / observation<textarea data-system="${i}" data-key="notes" rows="2">${esc(sys.notes)}</textarea></label></section>`).join('')}`;

  if(s.step===2)body=`<h2>Twelve months. One clear baseline.</h2><p class="section-intro">Record completed, consecutive calendar months. Solar means total generation; export is subtracted once. Other kWh accepts additional measured or calorifically converted carriers (including natural gas); document each conversion source. Excluded energy must be measured or assessed on the same energy basis.</p><div class="form-grid">${select('subtype','Reference building subtype',[['general','General A1 / A2'],['school','School · A3'],['tertiary','University / college · A3'],['multistorey','Multi-storey offices with lifts · G1'],['officepark','Separate office block / office park · G1']])}${field('benchmark','Occupancy / zone reference Eᵥ · kWh/m²/year','number')}${field('benchmarkSource','Licensed reference table, edition and clause')}${field('dieselFactor','Diesel conversion factor · kWh/L','number')}${field('lpgFactor','LPG conversion factor · kWh/kg','number')}</div>${field('factorSource','Gross calorific factor source and units (MJ/unit ÷ 3.6 = kWh/unit)')}<label class="check"><input type="checkbox" name="methodologyConfirmed" ${a.methodologyConfirmed?'checked':''}> I have verified the reference and A–G band methodology for this occupancy and energy zone.</label><div class="callout">${icon('bolt')}<span>Use verified gross calorific fuel energy on a thermal-equivalence basis. Do not apply generator efficiency. Enter MJ per unit divided by 3.6 as kWh per unit. Record fuel input once; do not also add its generated electricity.</span></div><button type="button" class="secondary" data-action="reference">Use guidance reference for selected subtype / zone</button><div class="ledger-toolbar"><b>Monthly energy ledger</b><button type="button" class="secondary" data-action="import-energy">Import CSV / Excel</button><button type="button" class="secondary" data-action="months">Populate previous 12 months</button></div><div class="table-wrap"><table class="ledger"><thead><tr><th>MONTH</th><th>GRID kWh</th><th>SOLAR kWh</th><th>EXPORT kWh</th><th>DIESEL L</th><th>LPG kg</th><th>OTHER kWh</th><th>EXCLUDED kWh</th></tr></thead><tbody>${a.months.map((m,i)=>`<tr>${['month','grid','solar','export','diesel','lpg','other','excluded'].map(key=>`<td><input aria-label="${esc(m.month)} ${key}" type="${key==='month'?'month':'number'}" ${key==='month'?'':'min="0" step="any"'} value="${esc(m[key]??0)}" data-month="${i}" data-key="${key}"></td>`).join('')}</tr>`).join('')}</tbody></table></div>${field('exclusionNotes','Excluded areas, streams and measurement method')}<div id="live-calculation" class="live-calculation"></div>`;

  if(s.step===3)body=`<h2>Evidence you can stand behind</h2><p class="section-intro">Attach utility bills, building plans and site audit proof. PDFs, PNGs and JPEGs up to 10 MB each. Evidence is locked on submission.</p><div class="form-grid">${field('professional','Issuing / assessing professional')}${field('professionalNumber','Professional registration / authorisation reference')}${field('auditBody','Site audit organisation / inspection body')}${field('auditReference','On-site audit log reference')}${field('auditDate','On-site audit date','date')}</div><div class="upload-zone"><span class="action-icon pink">${icon('report')}</span><div><h3>Build the evidence record</h3><p>Verify authorisation independently. A registration number entered here is not automatically verified.</p></div><button type="button" class="secondary" data-action="upload" ${locked?'disabled':''}>${icon('plus')} Add evidence</button></div>${documentList(a)}`;

  if(s.step===4)body=`<h2>Ready for an independent review?</h2><p class="section-intro">Check the complete record. Submitted evidence is frozen until a reviewer requests revisions.</p><div class="review-summary"><div><span class="eyebrow">PROPERTY</span><h3>${esc(a.name||'Unnamed property')}</h3><p>${esc(a.address)}</p>${badge(a.status)}</div><div><span class="eyebrow">REFERENCE</span><h3>${esc(a.occupancy)} · Zone ${a.zone}</h3><p>NFA ${number(a.nfa)} m² · GFA ${number(a.gfa)} m²</p></div></div><div id="validation-results" class="validation-results"><button type="button" class="secondary" data-action="validate">${icon('shield')} Run validation</button></div><div class="callout">${icon('shield')}<span>Submission requires 12 completed months, verified references, technical observations, professional details, and utility, plans and site-audit evidence. Review must be performed by a different person.</span></div>${!locked?'<button type="button" class="primary" data-action="submit-assessment">Submit for review '+icon('arrow')+'</button>':''}`;

  return heading('ASSESSMENT WORKSPACE',esc(a.name||'New building assessment'),`${a.propertyId?esc(a.propertyId)+' · ':''}${esc(a.status)}`,`<div class="button-row"><span id="save-state" class="muted">${locked?'Read-only record':'Draft changes save automatically'}</span><button class="secondary" data-action="back">Back to portfolio</button>${!locked?'<button class="primary" data-action="save">Save draft</button>':''}</div>`)+`<div class="wizard-layout"><nav class="wizard-steps" aria-label="Assessment steps">${titles.map((title,i)=>`<button class="wizard-step ${i===s.step?'current':''}" data-action="step" data-id="${i}" ${i===s.step?'aria-current="step"':''}><span>${i+1}</span><div><small>STEP ${i+1}</small><b>${title}</b></div></button>`).join('')}<div class="wizard-help">${icon('shield')}<b>Evidence matters.</b><p>${s.config.staticDemo?'Your changes are saved on this browser and recorded in its activity log.':'Your changes are private to your organisation and recorded in the audit trail.'}</p></div></nav><section class="panel wizard-content"><form id="wizard-form"><fieldset ${locked?'disabled':''}>${body}</fieldset></form><div class="wizard-controls"><button class="secondary" data-action="step" data-id="${Math.max(0,s.step-1)}" ${s.step===0?'disabled':''}>Previous</button><span>Step ${s.step+1} of 5</span><button class="${s.step<4?'primary':'secondary'}" data-action="step" data-id="${Math.min(4,s.step+1)}" ${s.step===4?'disabled':''}>Continue ${icon('arrow')}</button></div>${a.notes?.length?`<section class="review-notes"><h3>Reviewer feedback</h3>${a.notes.map(n=>`<div><b>${esc(n.field)}</b><p>${esc(n.comment)}</p><small>${esc(n.by)} · ${esc(n.at.slice(0,10))}</small></div>`).join('')}</section>`:''}</section></div>`;

}

function documentList(a){return `<div class="document-list">${s.data.documents.filter(d=>d.assessmentId===a.id).map(d=>`<div>${icon('report')}<span><b>${esc(d.name)}</b><small>${esc(d.kind)} · ${number(d.size/1024)} KB</small></span><a class="text-link" href="/api/documents/${d.id}">Download</a>${['Draft','Revision Required'].includes(a.status)?`<button type="button" class="icon-button" data-action="delete-document" data-id="${d.id}" aria-label="Remove ${esc(d.name)}">×</button>`:''}</div>`).join('')||'<p class="muted">No evidence attached yet.</p>'}</div>`;}

function readDraft(){if(!s.draft)return;$('#wizard-form')?.querySelectorAll('[name]').forEach(el=>{s.draft[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;});$('#wizard-form')?.querySelectorAll('[data-month]').forEach(el=>{s.draft.months[Number(el.dataset.month)][el.dataset.key]=el.type==='number'?Number(el.value):el.value;});$('#wizard-form')?.querySelectorAll('[data-system]').forEach(el=>{s.draft.systems[Number(el.dataset.system)][el.dataset.key]=el.value;});}

let pendingSave=Promise.resolve();

function saveDraft(silent=false){clearTimeout(saveTimer);saveTimer=null;readDraft();if(!['Admin','Super Admin','Assessor','Energy Manager'].includes(s.user?.role))return Promise.resolve(s.draft);const execute=async()=>{if(!s.draft||!['Draft','Revision Required'].includes(s.draft.status))return s.draft;const a=s.draft;if(!a.name?.trim()){if(!silent)throw new Error('Enter a property name first');return a;}$('#save-state')&&($('#save-state').textContent='Saving…');const snapshot=structuredClone(a);const saved=await api(a.id?`/assessments/${a.id}`:'/assessments',{method:a.id?'PUT':'POST',body:snapshot});if(s.draft===a){a.id=saved.id;a.version=saved.version;a.propertyId=saved.propertyId;a.createdBy=saved.createdBy;}$('#save-state')&&($('#save-state').textContent='All changes saved');if(!silent)toast('Assessment saved');return a;};pendingSave=pendingSave.catch(()=>{}).then(execute);return pendingSave;}

function blank(){const months=[];for(let i=0;i<12;i++){const d=new Date();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-12+i);months.push({month:d.toISOString().slice(0,7),grid:0,solar:0,export:0,diesel:0,lpg:0,other:0,excluded:0});}return {name:'',status:'Draft',address:'',province:'Gauteng',municipality:'',erf:'',occupancy:'G1',subtype:'officepark',ownership:'Private',zone:'1',gfa:0,nfa:0,vacancyAreaMonths:0,operationalYears:2,majorRenovation:false,benchmark:0,benchmarkSource:'',methodologyConfirmed:false,dieselFactor:0,lpgFactor:0,factorSource:'',months,systems:systemNames.map((title,i)=>({code:'XA'+(i+1),title,status:'Not assessed',notes:''})),notes:[]};}

function liveCalculation(){const a=s.draft,el=$('#live-calculation');if(!el)return;let energy=0,excluded=0;for(const m of a.months){energy+=m.grid+m.solar-m.export+m.diesel*a.dieselFactor+m.lpg*a.lpgFactor+(m.other||0);excluded+=m.excluded;}el.innerHTML=`<span><small>Included energy</small><b>${number(energy-excluded,1)} kWh</b></span><span><small>Energy intensity</small><b>${a.nfa>0?number((energy-excluded)/(a.nfa-(a.vacancyAreaMonths||0)/12),1):'—'} kWh/m²/yr</b></span><span><small>Excluded share</small><b>${energy>0?number(excluded/energy*100,1):0}%</b></span>`;}

async function detail(id){const a=s.data.assessments.find(a=>a.id===id);if(!a)return;const r=a.result,cert=s.data.certificates.find(c=>c.assessmentId===id);openModal(`<div class="eyebrow">${esc(a.propertyId)}</div><h2>${esc(a.name)}</h2><p class="muted">${esc(a.address)}</p><div class="detail-rating">${grade(r?.grade)}<div><strong>${r?number(r.eui,1):'—'}</strong><span>kWh/m²/year · ${esc(a.occupancy)} / Zone ${a.zone}</span></div>${badge(a.status)}</div><dl class="detail-list"><div><dt>Applicability</dt><dd>${r?.applicability.mandatory?'Meets mandatory screening criteria':'Voluntary / criteria not yet met'}</dd></div><div><dt>Benchmark source</dt><dd>${esc(a.benchmarkSource||'Not recorded')}</dd></div><div><dt>Excluded energy</dt><dd>${r?number(r.excluded)+' kWh ('+number(r.excludedPercent,1)+'%)':'—'}</dd></div></dl><div class="button-row">${targetsFor(a,s.user,s.config.staticDemo).length?`<button class="secondary" data-action="move-stage" data-id="${id}">Move stage</button>`:''}<button class="primary" data-action="edit" data-id="${id}">Open assessment ${icon('arrow')}</button><a class="secondary" target="_blank" rel="noopener" href="/api/assessments/${id}/pdf">${icon('download')} Review PDF</a>${a.status==='Approved'?`<button class="secondary" data-action="renew" data-id="${id}">Begin renewal</button>`:''}</div>${['Submitted','Under Review'].includes(a.status)?`<div class="review-box"><h3>Independent review</h3>${!s.config.staticDemo&&a.createdBy===s.user.id?'<p class="muted">Another authorised person must review this submission.</p>':a.status==='Submitted'?`<button class="primary" data-action="review-start" data-id="${id}">Start review</button>`:`<label class="check"><input type="checkbox" id="confirm-benchmark"> I independently verified the benchmark, factors and methodology.</label><label class="check"><input type="checkbox" id="confirm-professional"> I independently verified the professional’s registration / authorisation.</label><div class="form-grid"><label class="field">Field requiring revision<input id="review-field" placeholder="e.g. months, nfa, auditReference"></label><label class="field">Review / revision comment<textarea id="review-comment" rows="3"></textarea></label></div><div class="button-row"><button class="primary" data-action="approve" data-id="${id}">Approve assessment</button><button class="secondary" data-action="revision" data-id="${id}">Request revision</button></div>`}</div>`:''}${a.notes?.length?`<h3>Revision history</h3>${a.notes.map(n=>`<blockquote><b>${esc(n.field)}</b><p>${esc(n.comment)}</p></blockquote>`).join('')}`:''}${cert?`<p class="muted">Certificate record: ${esc(cert.internal)} · ${esc(cert.status)}</p>`:''}`);}

function csv(){const fields=['Property ID','Property','Province','Occupancy','Zone','GFA m2','NFA m2','EUI kWh/m2/year','Grade','Assessment status'];const cell=v=>{let t=String(v??'');if(/^(?:\s*[=+\-@]|[\t\r\n])/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"';};const rows=s.data.assessments.map(a=>[a.propertyId,a.name,a.province,a.occupancy,a.zone,a.gfa,a.nfa,a.result?.eui,a.result?.grade,a.status]);const blob=new Blob(['\ufeff'+[fields,...rows].map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bolide-energy-portfolio.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

async function validation(){const a=await saveDraft(true);if(!a.id)throw new Error('Save a named property first');const result=await api(`/assessments/${a.id}/validation`);const el=$('#validation-results');if(el)el.innerHTML=result.errors.length?`<h3>${result.errors.length} items need attention</h3><ul>${result.errors.map(e=>`<li><b>${esc(e.field)}</b> — ${esc(e.message)}</li>`).join('')}</ul>`:`<div class="success-box">${icon('check')} Submission checks passed. Independent review is still required.</div>`;return result;}

async function navigate(){if(s.page==='wizard'){clearTimeout(saveTimer);await saveDraft(true);}s.page=location.hash.slice(1)||'dashboard';if(!['dashboard','properties','assessments','certificates','savings','compliance','reports','team'].includes(s.page))s.page='dashboard';if(s.page==='team'&&['Admin','Super Admin'].includes(s.user?.role))s.team=await api('/team');await refresh();document.body.classList.remove('menu-open');render();}

document.addEventListener('input',e=>{if(e.target.dataset.finance){const key=e.target.dataset.finance;if(!e.target.checkValidity())return;const next={...s.financialAssumptions,[key]:Number(e.target.value)};try{for(const el of document.querySelectorAll('[data-financial-result]')){const i=s.data.initiatives.find(i=>i.id===el.dataset.financialResult);el.innerHTML=financialMetrics(i,next);}s.financialAssumptions=next;document.querySelector(`[data-finance-output="${key}"]`).textContent=e.target.value;localStorage.setItem('bolide-epc:financial-scenario',JSON.stringify(next));}catch(err){toast(err.message,true);}return;}if(e.target.id==='workspace-query'){updateWorkspaceSearch(e.target.value);return;}if(e.target.id==='search'){s.search=e.target.value;s.tablePage=1;renderPropertyResults();return;}if(e.target.closest('#wizard-form')){readDraft();liveCalculation();clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft(true).catch(e=>toast(e.message,true)),1000);}});

document.addEventListener('change',async e=>{try{if(e.target.dataset.savingsFilter){s.savingsFilters={...s.savingsFilters,[e.target.dataset.savingsFilter]:e.target.value};render();return;}if(e.target.id==='page-size'){s.pageSize=Number(e.target.value);s.tablePage=1;renderPropertyResults();}if(e.target.id==='sort-order'){s.sort=e.target.value;s.tablePage=1;renderPropertyResults();}if(e.target.id==='rating-filter'||e.target.id==='province-filter'){s[e.target.id==='rating-filter'?'filter':'province']=e.target.value;s.tablePage=1;renderPropertyResults();}if(e.target.dataset.initiative){const i=s.data.initiatives.find(i=>i.id===e.target.dataset.initiative);await api('/initiatives/'+i.id,{method:'PUT',body:{status:e.target.value,version:i.version}});await refresh();render();toast('Initiative updated');}if(e.target.closest('#wizard-form')){readDraft();liveCalculation();clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft(true).catch(e=>toast(e.message,true)),500);}}catch(err){toast(err.message,true);}});

document.addEventListener('click',async e=>{const link=e.target.closest('a[href]');if(s.config.staticDemo&&link){const href=link.getAttribute('href');if(href.startsWith('/api/')||href.startsWith('/verify/')){e.preventDefault();try{const download=await (await import('./showcase-api.js')).browserDownload(href);if(download){const a=document.createElement('a');a.href=URL.createObjectURL(download.blob);a.download=download.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}const id=href.split('/')[3],record=s.data.assessments.find(a=>a.id===id);if(record){openModal(`<h2>${esc(record.name)} · Review summary</h2><p>${esc(record.propertyId)} · ${esc(record.status)}</p><p>${esc(record.address)}</p><p>Energy intensity: ${number(record.result?.eui||0,1)} kWh/m²/year</p><p>Net floor area: ${number(record.nfa)} m² · ${esc(record.occupancy)} / Zone ${esc(record.zone)}</p><button class="primary" data-action="print">Print / save PDF</button>`);return;}toast('Official verification is available after external registration.');}catch(err){toast(err.message,true);}return;}}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;try{

  if(action==='clear-savings-filters'){s.savingsFilters={};render();return;}
  if(action==='collapse'){s.compactNav=!s.compactNav;document.body.classList.toggle('nav-compact',s.compactNav);syncWorkspaceControls(s);try{localStorage.setItem('bolide-epc:compact-nav',s.compactNav?'1':'0');}catch{}return;}if(action==='table-page'){s.tablePage=Number(id);renderPropertyResults();return;}if(action==='workspace-search')return searchWorkspace();if(action==='search-section'){closeModal();return;}if(action==='search-property'){closeModal();return detail(id);}if(action==='account')return openModal(`<h2>Account details</h2><p class="muted">${esc(s.user.email)} · ${esc(s.user.role)}</p><form id="account-form"><label class="field">Name and surname<input name="name" value="${esc(s.user.name)}" required minlength="2" maxlength="100" autocomplete="name"></label><h3>Change password</h3><p class="muted">Leave password fields empty to keep your current password.</p><label class="field">Current password<input name="currentPassword" type="password" autocomplete="current-password"></label><label class="field">New password · at least 12 characters<input name="newPassword" type="password" minlength="12" maxlength="200" autocomplete="new-password"></label><label class="field">Confirm new password<input name="confirmPassword" type="password" autocomplete="new-password"></label><button class="primary" type="submit">Save account details</button></form>`);if(action==='close')return closeModal();if(action==='legal')return legal(id);if(action==='menu'){const open=document.body.classList.toggle('menu-open');syncNavigationState();return;}

  if(action==='theme'){s.theme=applyTheme(s.theme==='dark'?'light':'dark');syncWorkspaceControls(s);return;}

  if(action==='cookie-save'){try{const remember=$('#theme-pref').checked;localStorage.setItem('epc-theme-disabled',String(!remember));if(!remember){localStorage.removeItem('epc-theme');localStorage.removeItem('bolide-epc:theme');}else localStorage.setItem('bolide-epc:theme',s.theme);}catch{}closeModal();return toast('Preferences saved');}

  if(action==='demo'){const result=await api('/demo-login',{method:'POST',body:{role:id}});s.user=result.user;s.csrf=result.csrf;closeModal();await navigate();return;}

  if(action==='logout'){if(s.page==='wizard')await saveDraft(true);await api('/logout',{method:'POST'});s.user=null;s.csrf=null;return render();}

  if(action==='demo-switch')return openModal(`<h2>Explore another role</h2><p>Use the Assessor to prepare a submission and the Reviewer to review it independently.</p><div class="button-row">${['Admin','Assessor','Reviewer'].map(r=>`<button class="secondary" data-action="demo" data-id="${r}">${r}</button>`).join('')}</div>`);

  if(action==='import'||action==='import-energy'){let assessmentId;if(action==='import-energy'){await saveDraft(true);assessmentId=s.draft?.id;if(!assessmentId)throw new Error('Save a named assessment first');}return openImport({api,openModal,closeModal,toast,type:action==='import-energy'?'energy':'properties',assessmentId,onComplete:async()=>{await refresh();if(action==='import-energy'){s.draft=structuredClone(s.data.assessments.find(a=>a.id===assessmentId));s.page='wizard';s.step=2;}else{s.page='properties';s.search='';s.tablePage=1;}render();liveCalculation();}});}if(action==='new'){s.draft=blank();s.step=0;s.page='wizard';render();return;}

  if(action==='move-stage'){const a=s.data.assessments.find(a=>a.id===id);const choices=targetsFor(a,s.user,s.config.staticDemo);return openModal(`<h2>Move assessment</h2><p>${esc(a.name)}</p><div class="button-row">${choices.map(status=>`<button class="primary" data-action="board-move" data-id="${id}" data-status="${status}">${status}</button>`).join('')}</div>`);}
  if(action==='board-move'){closeModal();return await moveAssessment(id,b.dataset.status);}
  if(action==='detail')return detail(id);

  if(action==='edit'){closeModal();s.draft=structuredClone(s.data.assessments.find(a=>a.id===id));s.step=0;s.page='wizard';render();return;}

  if(action==='save')return await saveDraft();

  if(action==='step'){readDraft();await saveDraft(true);s.step=Number(id);render();liveCalculation();return;}

  if(action==='back'){await saveDraft(true);s.page='properties';await refresh();render();return;}

  if(action==='months'){readDraft();if(s.draft.months.some(m=>m.grid||m.solar||m.diesel||m.lpg))throw new Error('The ledger already contains energy. Clear it deliberately before resetting months.');s.draft.months=blank().months;render();liveCalculation();return;}

  if(action==='reference'){readDraft();const values=s.config.references[s.draft.occupancy+'-'+s.draft.subtype];const value=values?.[s.config.zones.indexOf(String(s.draft.zone))];if(!value)throw new Error('Choose a subtype matching the occupancy.');s.draft.benchmark=value;s.draft.benchmarkSource=s.config.referenceSource;s.draft.methodologyConfirmed=false;render();liveCalculation();return toast('Guidance reference loaded. Verify the applicable licensed standard.');}

  if(action==='validate')return await validation();

  if(action==='submit-assessment'){const result=await validation();if(result.errors.length)return;const a=await api(`/assessments/${s.draft.id}/transition`,{method:'POST',body:{status:'Submitted',version:s.draft.version}});s.draft=a;await refresh();render();toast('Submitted for independent review');return;}

  if(action==='upload'){await saveDraft(true);if(!s.draft.id)throw new Error('Save a named property first');return openModal(`<h2>Attach evidence</h2><form id="upload-form"><label class="field">Evidence category<select name="kind">${options(['Utility bills','Building plans','Site audit','Meter calibration','Equipment specifications'],null)}</select></label><label class="field">File · PDF, PNG or JPEG · max 10 MB<input type="file" name="file" required accept="application/pdf,image/png,image/jpeg"></label><p class="muted">${s.config.staticDemo?'Files and records are saved on this browser.':'Uploaded evidence is encrypted and private to your organisation.'} Only attach documents you are authorised to process.</p><button class="primary" type="submit">Upload evidence</button></form>`);}

  if(action==='delete-document'){await api('/documents/'+id,{method:'DELETE'});await refresh();render();return toast('Evidence removed');}

  if(['review-start','approve','revision'].includes(action)){const a=s.data.assessments.find(a=>a.id===id);const status=action==='review-start'?'Under Review':action==='approve'?'Approved':'Revision Required';await api(`/assessments/${id}/transition`,{method:'POST',body:{status,version:a.version,field:$('#review-field')?.value,comment:$('#review-comment')?.value,confirmBenchmark:$('#confirm-benchmark')?.checked,confirmProfessional:$('#confirm-professional')?.checked}});closeModal();await refresh();render();return toast('Assessment '+status.toLowerCase());}

  if(action==='renew'){const a=await api(`/assessments/${id}/renew`,{method:'POST'});closeModal();s.draft=a;s.step=0;s.page='wizard';await refresh();render();return toast('Renewal draft created. Enter a fresh reporting period.');}

  if(action==='rating-filter'){s.filter=id;s.page='properties';render();return;}

  if(action==='restore')return openModal('<h2>Restore portfolio backup</h2><p>This replaces the records on this browser with your saved backup.</p><form id="restore-form"><label class="field">Portfolio JSON backup<input type="file" name="file" accept=".json" required></label><label class="check"><input type="checkbox" required> Replace this browser’s current portfolio</label><button class="primary" type="submit">Restore backup</button></form>');

  if(action==='backup'){await saveDraft(true);const blob=new Blob([JSON.stringify(await (await import('./showcase-api.js')).backupPortfolio(),null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='bolide-portfolio-backup.json';link.click();URL.revokeObjectURL(link.href);return;}

  if(action==='csv')return csv();if(action==='print')return window.print();

  if(action==='audit'){const rows=await api('/audit');return openModal(`<h2>Recorded activity</h2><p class="muted">Latest 200 organisation events. Sensitive values are excluded from this view.</p><div class="audit-list">${rows.map(r=>`<div><span>${esc(r.action)}</span><small>${esc(r.at)} · ${esc(r.user_id||'workspace-user')} · ${esc(r.target)}</small>${r.fields?.length?`<small>Changed: ${r.fields.map(esc).join(', ')}</small>`:''}</div>`).join('')||'No activity recorded.'}</div>`);}

  if(action==='initiative')return openModal(`<h2>A better building starts here</h2><form id="initiative-form"><label class="field">Property<select name="assessmentId" required>${s.data.assessments.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><label class="field">Initiative title<input name="title" required maxlength="160" placeholder="e.g. LED lighting upgrade"></label><div class="form-grid"><label class="field">Annual saved electricity · kWh<input name="kwh" type="number" min="0" step="any" required></label><label class="field">Electricity tariff · R/kWh<input name="tariff" type="number" min="0" step="any" required></label><label class="field">Capital investment · R<input name="cost" type="number" min="0" step="any" required></label><label class="field">Emissions factor · kgCO₂e/kWh<input name="emission" type="number" min="0" step="any" required></label></div><p class="muted">Use documented estimates. Simple payback excludes financing, escalation and operating costs. Avoid double-counting overlapping initiatives.</p><button class="primary" type="submit">Save initiative</button></form>`);

  if(action==='compliance'){const c=s.data.compliance.find(c=>c.framework===id);return openModal(`<h2>${esc(id)} evidence</h2><form id="compliance-form" data-framework="${esc(id)}" data-version="${c?.version||0}"><label class="field">Review status<select name="status">${options(['Not reviewed','In progress','Evidence recorded'],c?.status)}</select></label><label class="field">Evidence reference, owner and follow-up<textarea name="notes" rows="5" required maxlength="2000">${esc(c?.notes||'')}</textarea></label><button class="primary" type="submit">Save evidence note</button></form>`);}

  if(action==='invite')return openModal(`<h2>Invite a colleague</h2><form id="invite-form"><label class="field">Email address<input name="email" type="email" required></label><label class="field">Role<select name="role">${options(['Assessor','Reviewer','Energy Manager','Property Owner','Compliance Officer','Admin'],'Assessor')}</select></label><p class="muted">Creates a single-use invitation valid for 48 hours. Share its link securely with the intended colleague.</p><button class="primary" type="submit">Create invitation</button></form>`);

  if(action==='certificate'){const c=s.data.certificates.find(c=>c.id===id);return openModal(`<div class="eyebrow">${esc(c.internal)}</div><h2>Certificate record</h2>${badge(c.status)}<p>The official certificate is issued outside this platform. Attach that PDF before activation.</p>${c.status==='Draft (Pending SANEDI)'?`<form id="certificate-form" data-id="${id}"><label class="field">Official SANEDI NBEPR number<input name="sanedi" required maxlength="100"></label><label class="field">Official issue date<input name="issued" type="date" required></label><label class="field">Expiry shown on official EPC (maximum five years)<input name="expires" type="date" required></label><label class="field">Externally issued EPC · PDF<input name="file" type="file" accept="application/pdf" required></label><label class="check"><input type="checkbox" name="popia" required> POPIA processing authority and required data protection review are signed off.</label><label class="check"><input type="checkbox" name="professionalConfirmed" required> I verified the issuer’s authorisation and the issued EPC.</label><button class="primary" type="submit" ${s.config.issuance?'':'disabled'}>Activate record</button>${!s.config.issuance?'<p class="form-error">Activation is disabled for this installation.</p>':''}</form>`:''}${c.documentId?`<a class="secondary" href="/api/documents/${c.documentId}">Download issued EPC</a>`:''}<p><a class="text-link" href="/verify/${c.publicToken}" target="_blank" rel="noopener">Public verification ${icon('arrow')}</a></p>${c.status!=='Revoked'?`<form id="revoke-form" data-id="${id}"><label class="field">Revocation reason<textarea name="reason" required rows="2"></textarea></label><button class="danger" type="submit">Revoke certificate record</button></form>`:`<p>Revocation reason: ${esc(c.reason)}</p>`}`);}

}catch(err){toast(err.message,true);}});

document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id?.startsWith('legacy-import-'))return;const button=form.querySelector('[type="submit"]');if(button)button.disabled=true;try{const fd=new FormData(form),body=Object.fromEntries(fd);

  if(form.id==='board-transition-form'){const a=s.data.assessments.find(a=>a.id===form.dataset.id);await api(`/assessments/${a.id}/transition`,{method:'POST',body:{...body,status:form.dataset.status,version:a.version,confirmBenchmark:body.confirmBenchmark==='on',confirmProfessional:body.confirmProfessional==='on'}});closeModal();await refresh();render();toast('Assessment moved to '+form.dataset.status);}
  if(form.id==='restore-form'){await (await import('./showcase-api.js')).restorePortfolio(fd.get('file'));closeModal();await refresh();render();toast('Portfolio restored');}

  if(form.id==='account-form'){if(body.newPassword!==body.confirmPassword)throw new Error('New passwords do not match');const result=await api('/account',{method:'PUT',body});s.user=result.user;closeModal();render();toast('Account details updated');}if(form.id==='login-form'){const invite=new URLSearchParams(location.search).get('invite');const result=await api(invite?'/invites/accept':'/login',{method:'POST',body:{...body,token:invite}});s.user=result.user;s.csrf=result.csrf;history.replaceState(null,'','/');await navigate();}

  if(form.id==='upload-form'){await api(`/assessments/${s.draft.id}/documents`,{method:'POST',body:fd});closeModal();await refresh();render();toast('Evidence uploaded');}

  if(form.id==='initiative-form'){await api('/initiatives',{method:'POST',body});closeModal();await refresh();render();toast('Initiative saved');}

  if(form.id==='compliance-form'){await api('/compliance/'+encodeURIComponent(form.dataset.framework),{method:'PUT',body:{...body,version:Number(form.dataset.version)}});closeModal();await refresh();render();toast('Compliance evidence saved');}

  if(form.id==='invite-form'){const result=await api('/team/invite',{method:'POST',body});openModal(`<h2>Invitation created</h2><p>Share this single-use link securely. It expires in 48 hours.</p><label class="field">Invitation link<input readonly value="${esc(result.url)}" id="invite-link"></label><button class="primary" id="copy-invite">Copy link</button>`);$('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(result.url);toast('Invitation link copied');}catch{$('#invite-link').select();toast('Select and copy the invitation link');}};}

  if(form.id==='certificate-form'){const c=s.data.certificates.find(c=>c.id===form.dataset.id);const upload=new FormData();upload.append('kind','Issued EPC');upload.append('file',fd.get('file'));const d=await api(`/assessments/${c.assessmentId}/documents`,{method:'POST',body:upload});await api(`/certificates/${c.id}/activate`,{method:'POST',body:{version:c.version,sanedi:body.sanedi,issued:body.issued,expires:body.expires,popia:body.popia==='on',professionalConfirmed:body.professionalConfirmed==='on',documentId:d.id}});closeModal();await refresh();render();toast('Certificate record activated');}

  if(form.id==='revoke-form'){const c=s.data.certificates.find(c=>c.id===form.dataset.id);await api(`/certificates/${c.id}/revoke`,{method:'POST',body:{reason:body.reason,version:c.version}});closeModal();await refresh();render();toast('Certificate record revoked');}

}catch(err){if(form.id==='login-form')$('#login-error').textContent=err.message;else toast(err.message,true);}finally{if(button)button.disabled=false;}});

window.addEventListener('hashchange',()=>navigate().catch(e=>toast(e.message,true)));

window.addEventListener('beforeunload',e=>{if(s.page==='wizard'&&saveTimer){e.preventDefault();e.returnValue='';}});

async function start(){s.config=await api('/config');if(location.pathname.startsWith('/verify/')){const token=location.pathname.split('/').at(-1);let c;try{c=await api('/verify/'+token);}catch{app.innerHTML='<main class="verification"><h1>Record not found</h1><p>This verification link is unavailable.</p><a href="/">Open Energy Pro</a></main>';return;}app.innerHTML=`<main class="verification"><img src="/assets/bolide-logo.png" alt="Bolide"><div class="eyebrow">PUBLIC RECORD VERIFICATION</div><h1>Energy performance record</h1>${badge(c.status)}<dl>${Object.entries({Property:c.propertyId,'Internal tracking':c.internal,'SANEDI number':c.sanedi||'Not assigned',Issued:c.issued||'Not issued',Expires:c.expires||'Not issued'}).map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><p>${esc(c.notice)}</p><a href="https://epc.sanedi.org.za/home" target="_blank" rel="noopener">Check the SANEDI register ${icon('arrow')}</a></main>`;return;}

  try{const result=await api('/me');s.user=result.user;s.csrf=result.csrf;await navigate();}catch{login();}}

start().catch(e=>{app.innerHTML='<main class="verification"><h1>Workspace unavailable</h1><p>Check the server and refresh this page.</p></main>';toast(e.message,true);});







document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&s.user){e.preventDefault();if(modal.open)closeModal();searchWorkspace();}});

document.addEventListener('click',e=>{document.querySelectorAll('.account-menu[open]').forEach(menu=>{if(!menu.contains(e.target))menu.removeAttribute('open');});});

